# filename: analyze_db.py
import sqlite3

def main():
    # Step 1: Connect to the database
    print("Step 1: Connecting to database...")
    conn = sqlite3.connect('./database.db')
    cursor = conn.cursor()
    print("Database connected successfully.")

    # Step 2: Survey development_recommendations
    print("\nStep 2: Surveying lever__hiring_manager_scorecard.development_recommendations...")
    cursor.execute('SELECT DISTINCT "development_recommendations" FROM "lever__hiring_manager_scorecard"')
    distinct_values = cursor.fetchall()
    print(f"Found {len(distinct_values)} distinct development_recommendations values:")
    for val in distinct_values:
        print(f"  - {val[0]}")

    # Step 3: Compute total total_requisitions_owned across all rows
    print("\nStep 3: Computing total total_requisitions_owned...")
    cursor.execute('SELECT SUM(total_requisitions_owned) FROM "lever__hiring_manager_scorecard"')
    total_sum = cursor.fetchone()[0]
    print(f"Total total_requisitions_owned: {total_sum}")

    # Clean up
    conn.close()
    print("Database connection closed.")

    # Step 4: Final answer
    print("\nStep 4: Final answer")
    print(f"Final answer: {total_sum}")

if __name__ == '__main__':
